def once(source,old,new):
 if source.count(old)!=1:raise RuntimeError('Sorgente inatteso: '+old[:100]+'. Aggiornamento interrotto prima della compilazione.')
 return source.replace(old,new,1)

def patch_main(source):
 if MARKER in source:return source
 source=BASE.replace_method(source,'void addChoice()',ADD_CHOICE)
 source=BASE.replace_method(source,'void confirmDrug(JSONObject drug)',CONFIRM)
 source=once(source,'super.onActivityResult(req,result,data);','super.onActivityResult(req,result,data);if(req==30||req==31){photoResult(req,result,data);return;}')
 source=once(source,'void home(){','void home(){clearPhotoSession();')
 source=once(source,'void shell(String title,String subtitle){','void shell(String title,String subtitle){searchVersion++;')
 source=source.replace('Versione app 2.4.0','Versione app 2.5.0')
 end=source.rfind('}')
 if end<0:raise RuntimeError('MainActivity incompleta')
 return source[:end]+EXTRA+'\n'+source[end:]

def patch_catalog(source):
 if '// PHOTO_CATALOG_250' in source:return source
 end=source.rfind('}')
 if end<0:raise RuntimeError('Catalog incompleto')
 return source[:end]+CATALOG_EXTRA+'\n'+source[end:]

def patch_manifest(source):
 if '.PhotoActivity' in source:return source
 if 'android:name=".ScanActivity"' not in source:raise RuntimeError('Activity fotocamera originale non trovata')
 return source.replace('android:name=".ScanActivity"','android:name=".PhotoActivity"')

def patch_gradle(source):
 source=re.sub(r"\s*implementation 'com\.google\.mlkit:barcode-scanning:[^']+'",'',source)
 if 'com.google.mlkit:text-recognition:' not in source:
  source=once(source,'dependencies {',"dependencies {\n implementation 'com.google.mlkit:text-recognition:16.0.1'\n implementation 'androidx.exifinterface:exifinterface:1.3.7'")
 source=re.sub(r'\bversionCode\s+204\b','versionCode 205',source)
 return source.replace("versionName '2.4.0'","versionName '2.5.0'")

def main():
 previous.main()
 directory=Path('app/src/main/java/it/farmacidicasa')
 main_path=directory/'MainActivity.java';catalog=directory/'Catalog.java';manifest=Path('app/src/main/AndroidManifest.xml');gradle=Path('app/build.gradle')
 source=patch_main(main_path.read_text(encoding='utf-8'));cat=patch_catalog(catalog.read_text(encoding='utf-8'));mf=patch_manifest(manifest.read_text(encoding='utf-8'));build=patch_gradle(gradle.read_text(encoding='utf-8'))
 main_path.write_text(source,encoding='utf-8');catalog.write_text(cat,encoding='utf-8');manifest.write_text(mf,encoding='utf-8');gradle.write_text(build,encoding='utf-8')
 for name,content in FILES.items():
  dest=(Path('app/src/test/java/it/farmacidicasa') if name.endswith('Test.java') else directory)/name
  dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content,encoding='utf-8')
 old_scanner=directory/'ScanActivity.java'
 if old_scanner.exists():old_scanner.unlink()
 print('Versione 2.5: foto e OCR incorporato, candidati dal catalogo, foto nella conferma e confronto AIC. Nessun invio delle foto e nessun salvataggio automatico del medicinale. Le foto sono temporanee, non incluse nel backup.')

if __name__=='__main__':main()
